<?php
namespace App\Http\Controllers;
use App\Models\CitaVeterinaria; use App\Rules\OperatingHours; use App\Services\AuditoriaService; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Validation\Rule; use Illuminate\Validation\ValidationException; use Inertia\Inertia;
class CitaVeterinariaController extends Controller { public function create(){return Inertia::render('Citas/Create',['costo'=>(float)config('aquarium.consultation_fee',500)]);} public function store(Request $r,AuditoriaService $audit){$v=$r->validate(['nombre_mascota'=>'required|string|max:120','especie'=>'required|string|max:80','motivo'=>'required|string|max:2000','fecha_hora'=>['required','date','after:now',new OperatingHours]]);$c=DB::transaction(function()use($v,$r){$at=\Carbon\Carbon::parse($v['fecha_hora']);DB::select('select pg_advisory_xact_lock(hashtext(?))',[$at->toDateTimeString()]);if(CitaVeterinaria::where('fecha_hora',$at)->where('estatus','Pendiente')->where(fn($q)=>$q->whereNull('reservado_hasta')->orWhere('reservado_hasta','>',now()))->exists())throw ValidationException::withMessages(['fecha_hora'=>'Ese horario ya está ocupado.']);return CitaVeterinaria::create($v+['user_id'=>$r->user()->id,'estatus'=>'Pendiente','costo'=>config('aquarium.consultation_fee',500),'pago_confirmado'=>false,'reservado_hasta'=>now()->addMinutes(30)]);});$audit->registrar($r,'cita.creada:'.$c->id);return back()->with('success','Cita reservada 30 minutos; confirma el pago en caja.');} public function agenda(Request $r){$date=\Carbon\Carbon::parse($r->input('fecha',today()->toDateString()));return Inertia::render('Veterinaria/Agenda',['citas'=>CitaVeterinaria::with('user','expediente')->whereDate('fecha_hora',$date)->orderBy('fecha_hora')->get(),'fecha'=>$date->toDateString()]);} public function update(Request $r,CitaVeterinaria $cita,AuditoriaService $audit){$v=$r->validate(['estatus'=>['required',Rule::in(['Pendiente','Atendida','Cancelada'])],'motivo_cancelacion'=>'required_if:estatus,Cancelada|nullable|string|max:1000','reembolso_autorizado'=>'sometimes|boolean']);if(($v['estatus']??'')==='Cancelada'&&empty($v['motivo_cancelacion']))throw ValidationException::withMessages(['motivo_cancelacion'=>'Se requiere justificar la cancelación.']);if(($v['estatus']??'')==='Atendida'&&!$cita->pago_confirmado)throw ValidationException::withMessages(['estatus'=>'La consulta debe estar pagada para marcarla como atendida.']);if($cita->pago_confirmado&&($v['estatus']??'')==='Cancelada'&&!($v['reembolso_autorizado']??false))throw ValidationException::withMessages(['reembolso_autorizado'=>'El veterinario debe autorizar el reembolso total.']);$cita->update($v+['reservado_hasta'=>null]);$audit->registrar($r,'cita.actualizada:'.$cita->id);return back();} }
